import{_ as o}from"./plugin-vue_export-helper-c27b6911.js";import{r as p,o as r,c,f as l,b as a,d as s,a as e,e as t}from"./app-99de073f.js";const i={},d=a("h1",{id:"从买一台搬瓦工-vps-到自建代理-手动版-让-ai-帮你搞",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#从买一台搬瓦工-vps-到自建代理-手动版-让-ai-帮你搞","aria-hidden":"true"},"#"),s(" 从买一台搬瓦工 VPS 到自建代理：手动版 + 让 AI 帮你搞")],-1),u=a("p",null,"买了一台搬瓦工 CN2 GIA-E 的洛杉矶 VPS，搭成自己的海外出口，Windows 上用 v2rayN 直连。这篇把整个过程记下来：手动怎么做，踩了哪些坑，最后怎么把这摊事整个甩给 AI（Claude Code）去干。",-1),k=t(`<blockquote><p>文中所有 IP、UUID、密钥都是占位符，换成你自己的。<strong>服务器密码和 vless 链接别往外发，别手滑。</strong></p></blockquote><h2 id="先把方案定下来" tabindex="-1"><a class="header-anchor" href="#先把方案定下来" aria-hidden="true">#</a> 先把方案定下来</h2><p>VPS 选搬瓦工 CN2 GIA-E 的洛杉矶机房，回国走电信 CN2 GIA 精品线路，晚高峰也稳。系统用 Debian 12，干净、轻量、资料多。服务端装 Xray 官方脚本，不装面板，少一个暴露在公网的 Web 入口。协议用 VLESS + REALITY + xtls-rprx-vision，不用域名也不用证书，流量伪装成访问正常的 HTTPS 大站。客户端 Windows 用 v2rayN，Android 用 v2rayNG，macOS 用 Karing，都能直接导入 <code>vless://</code> 链接。</p><p>网上很多教程爱用 3x-ui 面板，点点鼠标就配好了，新手确实友好。可面板默认走 HTTP，得多放行一个端口，还容易被扫到，我个人不太想碰。再说身边有 AI 的话，直接写配置文件反而更省事。</p><h2 id="买机器" tabindex="-1"><a class="header-anchor" href="#买机器" aria-hidden="true">#</a> 买机器</h2><p>去搬瓦工官网，在套餐里找 <strong>CN2 GIA-E</strong>。这是它的高端线路系列，能在多个机房之间随便切，回国线路质量好。配置看自己，一个人当代理用，最低配（1 核 / 1GB 内存）完全够。价格和流量以官网为准，年付一般比月付划算。机房选洛杉矶 CN2 GIA，下单之后在 KiwiVM 面板里随时能迁到香港、日本这些地方。付款支持支付宝或 PayPal。</p><p>买完进 <strong>KiwiVM</strong> 控制面板（搬瓦工后台 Services → My Services → KiwiVM Control Panel）。</p><p>在里面要办三件事。先重装系统，Install new OS 选 <strong>Debian 12 x86_64</strong>。再记下 SSH 信息，首页就有 IP 和 SSH 端口，注意搬瓦工有的机器端口不是 22，以面板显示为准。最后在 Root password modification 里生成新的 root 密码，记下来。</p><h2 id="手动搭一遍-大概-15-分钟" tabindex="-1"><a class="header-anchor" href="#手动搭一遍-大概-15-分钟" aria-hidden="true">#</a> 手动搭一遍（大概 15 分钟）</h2><h3 id="先把密钥配上" tabindex="-1"><a class="header-anchor" href="#先把密钥配上" aria-hidden="true">#</a> 先把密钥配上</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 本机执行：把公钥传上去，以后免密登录</span>
ssh-copy-id <span class="token parameter variable">-p</span> <span class="token operator">&lt;</span>SSH端口<span class="token operator">&gt;</span> root@<span class="token operator">&lt;</span>VPS_IP<span class="token operator">&gt;</span>
<span class="token function">ssh</span> <span class="token parameter variable">-p</span> <span class="token operator">&lt;</span>SSH端口<span class="token operator">&gt;</span> root@<span class="token operator">&lt;</span>VPS_IP<span class="token operator">&gt;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>确认密钥能登录了，就把密码登录关掉：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">sed</span> <span class="token parameter variable">-i</span> <span class="token string">&#39;s/^#\\?PasswordAuthentication.*/PasswordAuthentication no/&#39;</span> /etc/ssh/sshd_config
systemctl restart <span class="token function">ssh</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="更新系统-顺手开-bbr" tabindex="-1"><a class="header-anchor" href="#更新系统-顺手开-bbr" aria-hidden="true">#</a> 更新系统，顺手开 BBR</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">apt</span> update <span class="token operator">&amp;&amp;</span> <span class="token function">apt</span> upgrade <span class="token parameter variable">-y</span>
<span class="token function">apt</span> <span class="token function">install</span> <span class="token parameter variable">-y</span> <span class="token function">curl</span> ca-certificates openssl

<span class="token comment"># BBR 拥塞控制，对跨洋链路提速明显</span>
<span class="token builtin class-name">printf</span> <span class="token string">&quot;net.core.default_qdisc=fq<span class="token entity" title="\\n">\\n</span>net.ipv4.tcp_congestion_control=bbr<span class="token entity" title="\\n">\\n</span>&quot;</span> <span class="token operator">&gt;&gt;</span> /etc/sysctl.conf
<span class="token function">sysctl</span> <span class="token parameter variable">-w</span> <span class="token assign-left variable">net.core.default_qdisc</span><span class="token operator">=</span>fq <span class="token assign-left variable">net.ipv4.tcp_congestion_control</span><span class="token operator">=</span>bbr
<span class="token function">sysctl</span> net.ipv4.tcp_congestion_control   <span class="token comment"># 输出 bbr 即成功</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>有个小坑：搬瓦工的系统镜像自带几条 <code>eth1</code> 相关的 sysctl 配置，执行 <code>sysctl -p</code> 会报 <code>cannot stat /proc/sys/net/ipv4/.../eth1/...</code>。忽略就行，用 <code>sysctl -w</code> 直接设置。</p></blockquote><h3 id="装-xray" tabindex="-1"><a class="header-anchor" href="#装-xray" aria-hidden="true">#</a> 装 Xray</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">bash</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">curl</span> <span class="token parameter variable">-fsSL</span> https://github.com/XTLS/Xray-install/raw/main/install-release.sh<span class="token variable">)</span></span>&quot;</span> @ <span class="token function">install</span>
xray version
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="生成-uuid、密钥和-shortid" tabindex="-1"><a class="header-anchor" href="#生成-uuid、密钥和-shortid" aria-hidden="true">#</a> 生成 UUID、密钥和 shortId</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>xray uuid                 <span class="token comment"># 用户 ID</span>
xray x25519               <span class="token comment"># 输出 PrivateKey 和 Password(PublicKey)</span>
openssl rand <span class="token parameter variable">-hex</span> <span class="token number">8</span>       <span class="token comment"># shortId</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>PrivateKey</code> 写进服务端配置，<code>Password (PublicKey)</code> 给客户端用，也就是链接里的 <code>pbk</code> 参数。别搞混了。</p><h3 id="挑一个伪装站" tabindex="-1"><a class="header-anchor" href="#挑一个伪装站" aria-hidden="true">#</a> 挑一个伪装站</h3><p>REALITY 会把「不认识的访问」原样转发给一个真实的大站，所以在外人看来，你的 VPS 就是那个网站。目标站得支持 TLS 1.3 和 HTTP/2，离 VPS 近、延迟低，还要<strong>兼容新版 Xray 的后量子密钥交换</strong>（后面踩坑那节细说）。</p><p>可以在 VPS 上先测一圈：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token keyword">for</span> <span class="token for-or-select variable">d</span> <span class="token keyword">in</span> www.apple.com dl.google.com www.cloudflare.com<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">echo</span> <span class="token parameter variable">-n</span> <span class="token string">&quot;<span class="token variable">$d</span>: &quot;</span>
  <span class="token function">curl</span> <span class="token parameter variable">-sI</span> <span class="token parameter variable">--tlsv1.3</span> <span class="token parameter variable">--http2</span> <span class="token parameter variable">-o</span> /dev/null <span class="token parameter variable">-w</span> <span class="token string">&quot;%{http_version} %{time_connect}s<span class="token entity" title="\\n">\\n</span>&quot;</span> https://<span class="token variable">$d</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我最后选了 <code>www.apple.com</code>。</p><h3 id="写配置" tabindex="-1"><a class="header-anchor" href="#写配置" aria-hidden="true">#</a> 写配置</h3><p>编辑 <code>/usr/local/etc/xray/config.json</code>：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;log&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;loglevel&quot;</span><span class="token operator">:</span> <span class="token string">&quot;warning&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token property">&quot;inbounds&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span>
    <span class="token property">&quot;listen&quot;</span><span class="token operator">:</span> <span class="token string">&quot;0.0.0.0&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;port&quot;</span><span class="token operator">:</span> <span class="token number">443</span><span class="token punctuation">,</span>
    <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;vless&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;settings&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token property">&quot;clients&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;UUID&gt;&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;flow&quot;</span><span class="token operator">:</span> <span class="token string">&quot;xtls-rprx-vision&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
      <span class="token property">&quot;decryption&quot;</span><span class="token operator">:</span> <span class="token string">&quot;none&quot;</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;streamSettings&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token property">&quot;network&quot;</span><span class="token operator">:</span> <span class="token string">&quot;tcp&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;security&quot;</span><span class="token operator">:</span> <span class="token string">&quot;reality&quot;</span><span class="token punctuation">,</span>
      <span class="token property">&quot;realitySettings&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;target&quot;</span><span class="token operator">:</span> <span class="token string">&quot;www.apple.com:443&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;serverNames&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;www.apple.com&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token property">&quot;privateKey&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;PrivateKey&gt;&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;shortIds&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;&lt;shortId&gt;&quot;</span><span class="token punctuation">]</span>
      <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;sniffing&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;enabled&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token property">&quot;destOverride&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;http&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;tls&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;quic&quot;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span>
  <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;outbounds&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;freedom&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;tag&quot;</span><span class="token operator">:</span> <span class="token string">&quot;direct&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;blackhole&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;tag&quot;</span><span class="token operator">:</span> <span class="token string">&quot;block&quot;</span> <span class="token punctuation">}</span>
  <span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;routing&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;rules&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;field&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;ip&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;geoip:private&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token property">&quot;outboundTag&quot;</span><span class="token operator">:</span> <span class="token string">&quot;block&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>端口就用 <strong>443</strong>。REALITY 伪装的本来就是普通 HTTPS 流量，443 最自然。有些教程叫你「避开 443」，那说的是面板端口，跟 REALITY 入站没关系。</p><p>校验、启动：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>xray run <span class="token parameter variable">-test</span> <span class="token parameter variable">-c</span> /usr/local/etc/xray/config.json   <span class="token comment"># 输出 Configuration OK</span>
systemctl <span class="token builtin class-name">enable</span> <span class="token parameter variable">--now</span> xray
systemctl restart xray
ss <span class="token parameter variable">-tlnp</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token number">443</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>机器上开了防火墙（ufw / iptables）的话，记得放行 443 和 SSH 端口。</p><h3 id="拼分享链接" tabindex="-1"><a class="header-anchor" href="#拼分享链接" aria-hidden="true">#</a> 拼分享链接</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>vless://&lt;UUID&gt;@&lt;VPS_IP&gt;:443?encryption=none&amp;flow=xtls-rprx-vision&amp;security=reality&amp;sni=www.apple.com&amp;fp=chrome&amp;pbk=&lt;PublicKey&gt;&amp;sid=&lt;shortId&gt;&amp;type=tcp#LA-BWH
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="客户端这头怎么弄-v2rayn" tabindex="-1"><a class="header-anchor" href="#客户端这头怎么弄-v2rayn" aria-hidden="true">#</a> 客户端这头怎么弄（v2rayN）</h2><p>去 GitHub 的 <code>2dust/v2rayN</code> 下最新 Release，选带 core 的包。把上面的 <code>vless://</code> 链接复制下来，回到 v2rayN 主界面按 <strong>Ctrl+V</strong> 导入。右键节点，点<strong>测试真连接延迟</strong>，能蹦出毫秒数就说明通了。</p><p>底部状态栏有两处要设：系统代理选<strong>自动配置系统代理</strong>，路由选<strong>绕过大陆</strong>，国内网站直连，别绕去美国再绕回来。然后浏览器打开 <code>ip.sb</code>，显示的是 VPS 的 IP，就成了。</p><h3 id="tun-到底要不要开" tabindex="-1"><a class="header-anchor" href="#tun-到底要不要开" aria-hidden="true">#</a> TUN 到底要不要开</h3><p>系统代理只对遵守系统代理设置的程序生效，浏览器算一个。TUN 模式会建一张虚拟网卡，把所有程序的流量都接管，命令行和 UDP 也在内，不过得用管理员权限跑。</p><p>只想让几条命令走代理的话，用不着 TUN，环境变量就够了（端口以 v2rayN 底部显示为准）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function-name function">proxy_on</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token punctuation">{</span> <span class="token builtin class-name">export</span> <span class="token assign-left variable">HTTPS_PROXY</span><span class="token operator">=</span>http://127.0.0.1:10808 <span class="token assign-left variable">HTTP_PROXY</span><span class="token operator">=</span>http://127.0.0.1:10808 <span class="token assign-left variable">ALL_PROXY</span><span class="token operator">=</span>socks5://127.0.0.1:10808<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token function-name function">proxy_off</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token builtin class-name">unset</span> HTTPS_PROXY HTTP_PROXY ALL_PROXY<span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提醒一句：电脑上要是装了公司的 VPN 客户端，开 TUN 很容易跟它抢路由，结果断网，或者内网打不开。</p></blockquote><h2 id="踩坑-连不上-原来是伪装站选错了" tabindex="-1"><a class="header-anchor" href="#踩坑-连不上-原来是伪装站选错了" aria-hidden="true">#</a> 踩坑：连不上，原来是伪装站选错了</h2><p>我第一次配的伪装站是 <code>www.microsoft.com</code>。本机到 VPS 的 443 端口能连通，不带密钥的访问也能被正常转发到微软，证书有效。<strong>可客户端就是连不上</strong>，测速显示 -1。</p><p>把服务端 loglevel 改成 <code>info</code> 之后，日志里刷了一屏：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>REALITY: processed invalid connection from x.x.x.x: handshake did not complete successfully
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>我先核对了密钥。<code>xray x25519 -i &lt;PrivateKey&gt;</code> 算出来的公钥跟客户端填的一致，排除。接着排除网络问题，在 VPS 上跑一个客户端连它自己，<strong>照样失败</strong>，说明跟本地网络无关，是配置的锅。最后做对比测试，只换伪装站，其他配置一概不动：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>www.microsoft.com  =&gt; 失败
www.apple.com      =&gt; 成功
dl.google.com      =&gt; 成功
www.cloudflare.com =&gt; 成功
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原因是这样的。新版 Xray 用 <code>fp=chrome</code> 指纹握手时，会带上后量子密钥交换（X25519MLKEM768），伪装目标要是不支持，握手就在半路失败了。所以挑目标站的时候，<strong>一定要做一次完整的代理连接测试</strong>，别只测「转发是否正常」。我第一次就只测了转发，以为没事，结果真正的故障被漏掉了。</p><p><strong>验证得端到端。</strong> 半截验证等于没验证。</p><h2 id="测速和线路检测" tabindex="-1"><a class="header-anchor" href="#测速和线路检测" aria-hidden="true">#</a> 测速和线路检测</h2><p>回国线路用 backtrace 看：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">curl</span> <span class="token parameter variable">-fsSL</span> <span class="token parameter variable">-o</span> backtrace https://github.com/oneclickvirt/backtrace/releases/latest/download/backtrace-linux-amd64
<span class="token function">chmod</span> +x backtrace <span class="token operator">&amp;&amp;</span> ./backtrace
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>我这台的结果如下：</p><table><thead><tr><th></th><th>电信</th><th>联通</th><th>移动</th></tr></thead><tbody><tr><td>北京</td><td>CN2 GIA</td><td>CN2 GIA</td><td>CMIN2</td></tr><tr><td>上海</td><td>未识别</td><td>CN2 GIA</td><td>CMIN2</td></tr><tr><td>广州</td><td>CN2 GT</td><td>CN2 GIA</td><td>CMIN2</td></tr><tr><td>成都</td><td>CN2 GIA</td><td>4837（普通）</td><td>CMIN2</td></tr></tbody></table><p>延迟上，到上海大约 130ms，到广州大约 160ms，没丢包。VPS 自己从 Cloudflare 下载，跑到约 875 Mbps。</p>`,57),v={href:"https://www.itdog.cn",target:"_blank",rel:"noopener noreferrer"},b=a("code",null,"IP:443",-1),h={href:"http://ping.pe",target:"_blank",rel:"noopener noreferrer"},m={href:"http://bench.sh",target:"_blank",rel:"noopener noreferrer"},g={href:"http://speed.cloudflare.com",target:"_blank",rel:"noopener noreferrer"},q=t(`<blockquote><p>在公司网络里测要小心。海外流量可能先从公司的国际出口（比如新加坡）绕出去，你测到的是公司出口的速度，跟 VPS 的真实水平没什么关系。想测国内直连，用家里宽带、手机流量或者 ITDOG。</p></blockquote><h2 id="让-ai-帮你搞定-claude-code" tabindex="-1"><a class="header-anchor" href="#让-ai-帮你搞定-claude-code" aria-hidden="true">#</a> 让 AI 帮你搞定（Claude Code）</h2><p>上面这一整套，我其实是让 Claude Code 在终端里直接干完的。它能执行本地命令，能通过 SSH 操作远程服务器，能读日志，出了问题还会自己排错。</p><h3 id="开工前准备" tabindex="-1"><a class="header-anchor" href="#开工前准备" aria-hidden="true">#</a> 开工前准备</h3><p>本机装好 Claude Code（或者别的能跑终端命令的 AI Agent）。本机要有 SSH 密钥，也就是 <code>~/.ssh/id_rsa.pub</code> 或 <code>id_ed25519.pub</code>，没有就 <code>ssh-keygen -t ed25519</code> 生成一个。再备好 VPS 的 IP、SSH 端口和 root 密码。</p><h3 id="提示词" tabindex="-1"><a class="header-anchor" href="#提示词" aria-hidden="true">#</a> 提示词</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>我买了一台搬瓦工 VPS，Debian 12，IP 是 &lt;VPS_IP&gt;，SSH 端口 &lt;端口&gt;，root 密码是 &lt;密码&gt;。
请帮我：
1. 把我本机的 SSH 公钥装到服务器上，后续用密钥登录；
2. 安装 Xray 官方版本，配置 VLESS + REALITY + xtls-rprx-vision，端口 443；
3. 开启 BBR；
4. 在服务器上做一次完整的客户端连接自测，确认能通；
5. 最后给我一条可以导入 v2rayN 的 vless:// 链接。
密码之后我会改，不用担心泄露。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="它实际干了啥" tabindex="-1"><a class="header-anchor" href="#它实际干了啥" aria-hidden="true">#</a> 它实际干了啥</h3><p>它先用 <code>expect</code> 自动输了一次密码，跑 <code>ssh-copy-id</code> 装上公钥，之后全程走密钥登录。然后检查系统版本、内存、端口占用，装 Xray，开 BBR，生成 UUID、密钥对和 shortId，再测了几个候选伪装站的 TLS 1.3 / HTTP/2 支持和延迟。写好配置之后先 <code>xray run -test</code> 校验，再重启服务。</p>`,9),y={href:"http://microsoft.com",target:"_blank",rel:"noopener noreferrer"},f=t(`<h3 id="让-ai-碰服务器-有几件事得盯着" tabindex="-1"><a class="header-anchor" href="#让-ai-碰服务器-有几件事得盯着" aria-hidden="true">#</a> 让 AI 碰服务器，有几件事得盯着</h3><p>密码只给新机器，只用一次。AI 装好密钥以后马上 <code>passwd</code> 改掉 root 密码，再关掉密码登录。</p><p>要明确让它「跑一次完整的客户端连接测试」，我踩的坑就是 AI 一开始只做了半截验证。</p><p>它每次执行命令之前，Claude Code 都会把命令内容摆出来给你看，删除、覆盖这类操作多留意一眼。还有，vless 链接和私钥都跟密码一个级别，别贴到公开的地方。</p><h2 id="搭完之后还有点事" tabindex="-1"><a class="header-anchor" href="#搭完之后还有点事" aria-hidden="true">#</a> 搭完之后还有点事</h2><p>先改 root 密码，关掉 SSH 密码登录。有空可以把 SSH 挪到非 22 端口，再装个 fail2ban。KiwiVM 里每月瞄一眼流量用量，定期 <code>apt upgrade</code>，Xray 升级的话重新执行一遍官方安装命令就行。链接要是泄露了，赶紧重新生成 UUID 和密钥。</p><p>常用命令放这儿：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>systemctl status xray          <span class="token comment"># 状态</span>
journalctl <span class="token parameter variable">-u</span> xray <span class="token parameter variable">-f</span>          <span class="token comment"># 实时日志</span>
xray run <span class="token parameter variable">-test</span> <span class="token parameter variable">-c</span> /usr/local/etc/xray/config.json   <span class="token comment"># 校验配置</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最后唠叨一句，自建代理请遵守当地法律法规和各个服务的使用条款，在公司网络里用之前，也先翻翻公司的安全规定。</p>`,9);function x(_,S){const n=p("ExternalLinkIcon");return r(),c("div",null,[d,u,l(" more "),k,a("p",null,[s("别的工具也顺手列一下。全国多节点的延迟和丢包，用 "),a("a",v,[s("ITDOG"),e(n)]),s("（选 TCPing，填 "),b,s("）或 "),a("a",h,[s("ping.pe"),e(n)]),s("。逐跳路由用 NextTrace。VPS 综合性能看 "),a("a",m,[s("bench.sh"),e(n)]),s("、YABS、融合怪 ecs。点对点带宽用 iperf3。客户端实测就用 v2rayN 自带的测速，或者 "),a("a",g,[s("speed.cloudflare.com"),e(n)]),s("。")]),q,a("p",null,[s("等我反馈「连不上」，它就把日志调成 info，在本机下载同版本的 Xray 客户端来复现问题，又在 VPS 上自己连自己排除网络因素，最后逐个对比伪装站，定位到 "),a("a",y,[s("microsoft.com"),e(n)]),s(" 的兼容问题并修好。收尾时顺手用 backtrace、ping 和下载测试把线路质量也测了。")]),f])}const I=o(i,[["render",x],["__file","vps-to-vpn.html.vue"]]);export{I as default};
